const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Salta Province, Argentina geometry
  const saltaProvince = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Salta'));

  const geometry = saltaProvince.geometry();

  // 2. Load Hansen Global Forest Change dataset
  const hansenData = ee.Image('UMD/hansen/global_forest_change_2023_v1_10');

  // 3. Extract forest cover for year 2000 and 2019
  // treecover2000 = % tree cover in 2000
  const treecover2000 = hansenData.select('treecover2000');

  // lossyear band: year of loss (1=2001, 2=2002, ..., 19=2019)
  // Create forest cover for 2019 by removing areas that lost forest by 2019
  const lossYear = hansenData.select('loss').eq(1);
  const lossYearValue = hansenData.select('lossyear');

  // Forest cover 2019 = treecover2000 - areas lost by 2019
  // Areas lost by 2019 have lossyear values 1-19
  const forestLoss2000to2019 = treecover2000.mask(lossYear).updateMask(lossYearValue.lte(19));

  // 4. Calculate mean forest cover in 2000
  const cover2000 = treecover2000.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  const cover2000Value = cover2000.get('treecover2000').getInfo();

  // 5. Calculate total forest loss from 2000 to 2019
  const lossArea = hansenData.select('loss_area').reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  const lossAreaValue = lossArea.get('loss_area').getInfo();

  // 6. Get pixel count of valid data
  const validPixels2000 = treecover2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  const validPixelsValue = validPixels2000.get('treecover2000').getInfo();

  // 7. Validation and output
  console.log(`Salta Province Analysis 2000-2019:`);
  console.log(`Forest Cover 2000: ${cover2000Value !== null ? cover2000Value.toFixed(2) : 'N/A'}%`);
  console.log(`Forest Loss 2000-2019: ${lossAreaValue !== null ? lossAreaValue.toFixed(0) : 'N/A'} hectares`);
  console.log(`Valid Pixels: ${validPixelsValue}`);

  // 8. Determine answer
  if (validPixelsValue === null || validPixelsValue === 0) {
    console.log('C2');
  } else if (cover2000Value === null || lossAreaValue === null) {
    console.log('C3');
  } else if (lossAreaValue > 0) {
    // Forest loss occurred = forest cover decreased
    console.log('A');
  } else {
    // No forest loss = forest cover did not decrease
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
